"""Lightweight SVG/HTML review overlays over existing pixels. No image processing."""
from pathlib import Path
import json,html,hashlib
root=Path(__file__).resolve().parents[3];src=Path(__file__).parent;r=json.loads((src/'review.json').read_text());out=root/'runs/hemp-organ-review-v1';out.mkdir(exist_ok=True)
image='/'+r['reference'];mask='/runs/hemp-sam3-tiles-v1/results/reference/grid-3/standard-complete.png'
ref=root/r['reference'];r['image_sha256']=hashlib.sha256(ref.read_bytes()).hexdigest();(out/'review.json').write_text(json.dumps(r,indent=2)+'\n')
def panel(region,photo,marks):
 x,y,w,h=region['crop_xywh'];s=f'<svg viewBox="{x} {y} {w} {h}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="{region["id"]} enlarged existing pixels"><image href="{photo}" x="0" y="0" width="381" height="444"/>'
 if marks:
  a,b,c,d=region['review_roi_xyxy'];s+=f'<rect x="{a}" y="{b}" width="{c-a}" height="{d-b}" fill="none" stroke="#ffc761" stroke-width=".45" stroke-dasharray="2,1"/>'
  j,k=region['junction_hypothesis_xy'] if region['junction_hypothesis_xy'] else (-100,-100);s+=f'<path d="M{j-2},{k}h4 M{j},{k-2}v4" stroke="#ffc761" stroke-width=".5"/>'
  for i,a in enumerate(region['anchors']):
   j,k=a['xy'];s+=f'<circle cx="{j}" cy="{k}" r="1.2" fill="none" stroke="#fff" stroke-width=".45"/><text x="{j+2}" y="{k}" font-size="3" fill="white">{i+1}</text>'
 return s+'</svg>'
page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Plant organ identity review</title><style>body{font:17px system-ui;background:#eff1e8;color:#213b30;max-width:1280px;padding:28px;margin:auto}p{line-height:1.5;max-width:1000px}section{background:#fff;padding:20px;border-radius:14px;margin:22px 0}svg{width:100%;display:block;background:#10150d;max-height:430px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.note{background:#fff0cf;padding:16px;border-radius:10px}figcaption{padding:8px 0;font-size:14px}a{color:#23644f}img{max-width:100%}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style><h1>What exactly are we counting?</h1><p>One compound leaf contains several leaflets. Zoomed crops sometimes switch between these anatomical levels. This review preserves candidate groupings and individual visible surfaces separately.</p><p class="note"><b>Provisional assistant annotations, not expert labels or ground-truth masks.</b> Dashed boxes are review regions, not leaf boundaries. Circles are candidate visible-surface anchors; the cross is a hypothesized junction. Pixel enlargement adds no detail. These regions were selected after inspecting SAM3 and cannot serve as a held-out accuracy test.</p>'''
for reg in r['regions']:
 page+=f'<section><h2>{html.escape(reg["id"])}</h2><p>{html.escape(reg["question"])}</p><div class="grid">'
 for label,path,marks in [('Reference pixels',image,False),('Provisional identity anchors',image,True),('SAM3 3×3 predictions',mask,False)]:page+=f'<div>{panel(reg,path,marks)}<figcaption>{label}</figcaption></div>'
 page+=f'</div><p>{html.escape(reg["connection_status"])}. Both anchor boundaries remain untraced.</p></section>'
page+='''<section><h2>Errors caught during review</h2><p>An initial central anchor was on the main stem. Another lower-right anchor was in a gap near a leaf edge. Both were corrected after inspecting enlarged reference pixels; the original proposals are preserved in the source folder. The central shared-fan assumption was removed. Our own annotations need scrutiny as well as the model predictions.</p></section><section><h2>What remains unresolved</h2><p>The dense interior and shoot tips contain overlapping structures that this image cannot reliably separate. Do not fill them with invented organ labels, infer a total plant count, or fit geometry to raw mask totals. A point inside a prediction does not establish that its boundary is correct.</p><p>Before quantitative real-photo scoring, review these anchors, trace only resolvable visible boundaries, mark ambiguous pixels explicitly, and obtain a separate image for testing. Whole-leaf and leaflet masks need separate IDs linked by an uncertain parent relation where appropriate.</p></section><section><h2>The 3D model remains a hypothesis</h2><img src="/runs/hemp-photo-fit-v1/geometry-review.png"><p>Existing side/top views were inspected: the model is thin in depth because it is constrained by one view. These are predictions, not corroborating photographs. Better front-view segmentation cannot validate the unseen back of the plant.</p></section>'''
page+=f'<p>Reference: <a href="{r["source_url"]}">Anderson et al., PLOS ONE Fig. 1</a>, CC BY. <a href="review.json">Annotation metadata</a> · <a href="/runs/hemp-sam3-tiles-v1/index.html">Tiled comparison</a></p>'
(out/'index.html').write_text(page);print(out/'index.html')
